package com.apartment.service;
import java.sql.*; import java.time.*;
public class ComplaintService { private final Connection c; public ComplaintService(Connection c){this.c=c;} public void updateStatus(long id,String status,String actor)throws SQLException{if(!status.matches("Open|In Progress|Resolved"))throw new ValidationException("Invalid status"); c.setAutoCommit(false); try{String old; LocalDate complaintDate; try(var p=c.prepareStatement("SELECT status,complaint_date FROM complaint WHERE complaint_id=? FOR UPDATE")){p.setLong(1,id);try(var rs=p.executeQuery()){if(!rs.next())throw new AppException("Complaint not found");old=rs.getString(1);complaintDate=rs.getDate(2).toLocalDate();}} boolean valid=(old.equals("Open")&&status.equals("In Progress"))||(old.equals("In Progress")&&status.equals("Resolved")); if(!valid)throw new ValidationException("Only Open -> In Progress -> Resolved is allowed"); try(var p=c.prepareStatement("UPDATE complaint SET status=?,assigned_to=?,resolution_date=?,resolution_days=? WHERE complaint_id=?")){p.setString(1,status);p.setString(2,actor);if(status.equals("Resolved")){LocalDate now=LocalDate.now();p.setDate(3,Date.valueOf(now));p.setLong(4,Duration.between(complaintDate.atStartOfDay(),now.atStartOfDay()).toDays());}else{p.setNull(3,Types.DATE);p.setNull(4,Types.INTEGER);}p.setLong(5,id);p.executeUpdate();} c.commit();}catch(Exception e){c.rollback();if(e instanceof SQLException se)throw se;if(e instanceof RuntimeException re)throw re;throw new AppException("Status update failed",e);}finally{c.setAutoCommit(true);}} }
